import csv, math
p = "ae_ip_termination_by_month.csv"
with open(p) as f:
    r = csv.reader(f)
    header = next(r)
    rows = list(r)
print("header:", header)
print("nrows:", len(rows))
def fnum(x):
    try:
        return float(x)
    except Exception:
        return None
cols = [h.strip().lower() for h in header]
def find(*names):
    for i, c in enumerate(cols):
        if any(n in c for n in names):
            return i
    return None
i_diag = find("diagnos")
i_month = find("month")
i_rec = find("recov")
i_ae = find("ae")
print("idx diag,month,rec,ae:", i_diag, i_month, i_rec, i_ae)
flag = 0
if None not in (i_diag, i_rec, i_ae):
    for row in rows:
        rec = fnum(row[i_rec]); ae = fnum(row[i_ae])
        if rec is None or ae is None or ae <= 0:
            continue
        E = rec / ae
        z = (rec - E) / math.sqrt(E) if E > 0 else 0.0
        if abs(z) >= 2.0 and E >= 20:
            flag += 1
            print("FLAG", row[i_diag], row[i_month] if i_month is not None else "?", "A=%s E=%.1f z=%.2f" % (rec, E, z))
print("flags:", flag)
print("--- full table ---")
for row in rows:
    print(",".join(row))
